var n=`0032-pierogi-with-cabbage-and-mushrooms`;var t=`world-0032`;var o=`PL`;var a=`eastern-europe`;var l=4;var s=77;var r={en:`Pierogi with Cabbage and Mushrooms`,ua:`Пироги з капустою та грибами`};var g={en:`A classic dish from Poland, featuring chicken egg, sauerkraut, dried porcini, yellow onion. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Польща. Основні складники: куряче яйце, квашена капуста, сушені білі гриби, жовта цибуля. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 25 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 25 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:25,i:[[`all-purpose-flour`,480,`g`],[`water`,230,`ml`],[`chicken-egg`,1,`pcs`],[`table-salt`,4,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:20,i:[[`sauerkraut`,480,`g`],[`dried-porcini`,25,`g`],[`yellow-onion`,130,`g`],[`sunflower-oil`,35,`ml`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Roll the rested dough thinly, cut rounds, place filling in the center and pinch each dumpling tightly closed.`,ua:`Тонко розкачайте відпочиле тісто, виріжте кружальця, викладіть начинку в центр і ретельно заліпіть краї кожного вареника чи пельменя.`,t:[`rolling-out-dough`,`pinching-dumplings`],m:24,i:[]},{en:`Cook dumplings in batches in gently boiling salted water for about 6 minutes, until they float and the filling is cooked through. Lift out with a slotted spoon.`,ua:`Варіть вироби порціями в ледь киплячій підсоленій воді приблизно 6 хвилин, доки вони спливуть і начинка приготується. Вийміть шумівкою.`,t:[`boiling`],m:6,i:[[`water`,1400,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`unsalted-butter`,40,`g`]]}];var d={slug:n,id:t,country:`PL`,region:a,servings:4,minutes:77,title:r,text:g,steps:u};export{o as country,d as default,t as id,s as minutes,a as region,l as servings,n as slug,u as steps,g as text,r as title};